				return migratedConns, trace.Wrap(err)
			}
			newTeams[i] = types.TeamMapping{
				Organization: team.Organization,
				Team:         team.Team,
				Logins:       []string{r.GetName()},
			}
		}
		conn.SetTeamsToLogins(newTeams)
		if err := asrv.UpsertGithubConnector(conn); err != nil {
			return migratedConns, trace.Wrap(err)
